  BATTERY_VOLTAGE: 48,
  BATTERY_KWH: 40,
  SOC_MIN: 10,
  SOC_MAX: 95,
  SOC_DISCHARGE_MIN: 15,
  SOC_CRITICAL: 15,
  CHARGE_THRESHOLD: 0.80,
  DISCHARGE_THRESHOLD: 1.20,
  CHARGE_ABS_RATIO: 0.55,
  DISCHARGE_ABS_RATIO: 0.55,
  DISCHARGE_OVERSHOOT: 1.25,
  EXPORT_BIAS_W: 800,
  HYSTERESIS: 0.05,
  SOLAR_SURPLUS_W: 500,
  SOLAR_SURPLUS_EXIT_W: 200,
  ROUND_TRIP_EFF: 0.85,
  GRID_MAX_A_PHASE: 18,
  GRID_VOLTAGE: 230,
  SAFETY_MARGIN_A: 2,
  MIN_DISCHARGE_A: 35,
  MIN_CHARGE_A: 10,
  SOLAR_SUPPRESS_DISCHARGE_W: 500,
  EV_RATE_LIMIT_MS: 15 * 60 * 1000,
  EV_PUBLIC_RATE: 0.50,
