var evLastPollMs = context.get('evLastPollMs') || 0;
var evDtPolls = evLastPollMs > 0 ? Math.max(0, Math.min(10, (nowMs - evLastPollMs) / EV_POLL_MS)) : 1;
context.set('evLastPollMs', nowMs);

// ── Battery charge hold-down ──────────────────────────────────────────────────
var EV_CHARGE_HOLDDOWN_CYCLES = 4;
var wasCharging = context.get('battWasCharging') || false;
var holdDownCount = context.get('evHoldDownCount') || 0;
if (charging) {
  holdDownCount = 0;
} else if (wasCharging && !charging) {
  holdDownCount = 1;
} else if (holdDownCount > 0 && holdDownCount < EV_CHARGE_HOLDDOWN_CYCLES) {
  holdDownCount++;
} else {
  holdDownCount = 0;
}
context.set('battWasCharging', charging);
context.set('evHoldDownCount', holdDownCount);
var evInHoldDown = holdDownCount > 0;

// ── Phase loads — raw DSMR, no add-back ──────────────────────────────────────
var evCurrentPerPhase = lastEvAmps;
var evIn3Phase = lastEvAmps >= EV_3PHASE_MIN_A;
var phaseL1LoadA = (phaseL1kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL2LoadA = (phaseL2kW * 1000) / CFG.GRID_VOLTAGE;
var phaseL3LoadA = (phaseL3kW * 1000) / CFG.GRID_VOLTAGE;

// ── Overload detection (v2.20) ────────────────────────────────────────────────
// Confirmed overload: any phase > EV_OVERLOAD_FAST_A (22A) at once, or > 20A on
// two consecutive polls. Single marginal spikes between 20 and 22A are ignored.
// Response:
//   EV on 3 phases → trim: lower the amps by the excess (rounded up) and stay on
//                    3 phases — no Zaptec session restart. Only if that would go
//                    below 7A → soft cut to 6A single-phase.
//   EV single-phase (6A or less) → session cut (5A + cooldown), but only when the
//                    overload is on the EV's own phase.
