var maxPhaseLoad = Math.max(phaseL1LoadA, phaseL2LoadA, phaseL3LoadA);
var anyOver20 = maxPhaseLoad > EV_L1_HARD_LIMIT;
var evOverPrev = context.get('evOverPrev') || false;
context.set('evOverPrev', anyOver20);
var overConfirmed = evCarConnected && (maxPhaseLoad > EV_OVERLOAD_FAST_A || (anyOver20 && evOverPrev));
var overExcessA = Math.max(0, maxPhaseLoad - EV_L1_HARD_LIMIT);
var evPhaseLoadA = [phaseL1LoadA, phaseL2LoadA, phaseL3LoadA][EV_1PH - 1];
var trimAmps = lastEvAmps - Math.ceil(overExcessA + EV_TRIM_MARGIN_A);
var evTrim = overConfirmed && evIn3Phase && trimAmps >= EV_3PHASE_MIN_A;
var l1SoftCut = overConfirmed && lastEvAmps > EV_MIN_AMPS && !evTrim;
var l1SessionCut = overConfirmed && lastEvAmps <= EV_MIN_AMPS && evPhaseLoadA > EV_L1_HARD_LIMIT;

// Overload hold
var evHoldPolls = context.get('evHoldPolls') || 0;
var evHoldAmps = context.get('evHoldAmps') || 0;
var evHoldMode = context.get('evHoldMode') || '3-phase';
if (!evCarConnected || l1SessionCut) {
  evHoldPolls = 0;
} else if (evTrim) {
  evHoldPolls = EV_HOLD_POLLS; evHoldAmps = trimAmps; evHoldMode = '3-phase';
} else if (l1SoftCut) {
  evHoldPolls = EV_HOLD_POLLS; evHoldAmps = EV_MIN_AMPS; evHoldMode = EV_1PH_LABEL;
} else if (evHoldPolls > 0) {
  evHoldPolls = Math.max(0, evHoldPolls - evDtPolls);
}
context.set('evHoldPolls', evHoldPolls);
context.set('evHoldAmps', evHoldAmps);
context.set('evHoldMode', evHoldMode);
var inEvHold = evHoldPolls > 0 && !evTrim && !l1SoftCut;

// ── EV low-SoC priority (with hysteresis) ────────────────────────────────────
var evLowSoc = context.get('evLowSocActive') || false;
if (!evCarConnected || !evSoCKnown) {
  evLowSoc = false;
} else if (evSoC < EV_SOC_PRIORITY_ON) {
